// <auto-generated />
namespace Alpha.CloneAccount.Api.Filters
{
    using System.Net;
    using System.Net.Http;
    using System.Text;
    using System.Web.Http.Filters;
    using Fanex.Logging.Extensions.Web;

    internal sealed class GlobalExceptionFilter : ExceptionFilterAttribute
    {
        public override void OnException(HttpActionExecutedContext actionExecutedContext)
        {
            if (actionExecutedContext != null)
            {
                var exception = actionExecutedContext.Exception;

                var messageBuilder = new StringBuilder();
                messageBuilder
                    .Append("Message: ")
                    .Append(exception.Message)
                    .AppendLine()
                    .Append("Type: ")
                    .Append(exception.GetType().ToString())
                    .AppendLine()
                    .Append("Source: ")
                    .Append(exception.Source)
                    .AppendLine()
                    .Append("Url: ")
                    .Append(actionExecutedContext.Request.RequestUri.OriginalString)
                    .AppendLine();

                ExceptionHandler.Handle(exception);

                actionExecutedContext.Response = actionExecutedContext.Request.CreateErrorResponse(
                    HttpStatusCode.InternalServerError, messageBuilder.ToString());
            }

            base.OnException(actionExecutedContext);
        }
    }
}